package com.thang.nihongo_user.controller;
import com.thang.nihongo_user.service.AdminCommerceService;import com.thang.nihongo_user.repository.AdminCommerceAuditRepository;import com.nihongo.security.SafeCsv;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.http.*;import org.springframework.data.domain.PageRequest;import java.util.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/nihongo-user/admin/commerce") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')")
public class CommerceExportController {
 private final AdminCommerceService commerce;private final AdminCommerceAuditRepository audit;private final com.thang.nihongo_user.repository.IWalletDepositRepository deposits;
 @GetMapping("/revenue/export") public ResponseEntity<byte[]> revenue(@RequestParam LocalDate from,@RequestParam LocalDate to){var report=commerce.revenue(from,to);List<List<?>> rows=new ArrayList<>(report.byCourse().stream().map(s->Arrays.asList(s.courseId(),s.courseName(),s.renewal()?"Gia hạn":"Mua mới",s.purchases(),s.amount())).toList());rows.add(Arrays.asList(null,"Hoàn về ví trong khoảng ngày","Hoàn tiền",0,report.refunds().negate()));return csv("revenue.csv",List.of("Mã khóa","Khóa học","Loại","Lượt mua","Tiền sau khuyến mãi"),rows);}
 @GetMapping("/audit/export") public ResponseEntity<byte[]> audit(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to){var dates=com.nihongo.security.CsvDates.validate(from,to);var records=audit.findByCreatedAtGreaterThanEqualAndCreatedAtLessThanOrderByCreatedAtDescIdDesc(dates.from().atStartOfDay(),dates.to().plusDays(1).atStartOfDay(),PageRequest.of(0,10000));if(records.getTotalElements()>10000)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Nhật ký vượt 10000 dòng");return csv("commerce-audit.csv",List.of("Thời gian","Người thao tác","Hành động","Đối tượng","Chi tiết"),records.getContent().stream().map(a->Arrays.asList(a.getCreatedAt(),a.getActor(),a.getAction(),a.getTarget(),a.getDetail())).toList());}
 @GetMapping("/deposit-audit/export") public ResponseEntity<byte[]> deposits(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to){var dates=com.nihongo.security.CsvDates.validate(from,to);var result=deposits.findByReviewedAtGreaterThanEqualAndReviewedAtLessThanOrderByReviewedAtDescIdDesc(dates.from().atStartOfDay(),dates.to().plusDays(1).atStartOfDay(),PageRequest.of(0,10000));if(result.getTotalElements()>10000)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Nhật ký vượt 10000 dòng");return csv("deposit-audit.csv",List.of("Thời gian","Người duyệt","Mã nạp","Số tiền","Trạng thái","Tham chiếu","Ghi chú"),result.getContent().stream().map(d->Arrays.asList(d.getReviewedAt(),d.getReviewedBy(),d.getId(),d.getAmount(),d.getStatus(),d.getBankReference(),d.getReviewNote())).toList());}
 private ResponseEntity<byte[]> csv(String name,List<String> header,List<? extends List<?>> rows){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+name).contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(SafeCsv.write(header,rows));}
}
